import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("upload a document", { tag: "@DOC-01" }, async ({ apiAs }) => {
  // Arrange: a vendor in draft status, created through the API
  const member = await apiAs("member");
  const vendorRes = await member.post("/api/vendors", {
    data: {
      name: uniqueName("Doc Vendor"),
      category: "services",
      contact_email: `doc-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(vendorRes.status(), await vendorRes.text()).toBe(201);
  const vendor = await vendorRes.json();
  expect(vendor.status).toBe("draft");

  // Act: upload the insurance certificate
  const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "insurance_certificate",
      file: {
        name: "insurance_certificate.txt",
        mimeType: "text/plain",
        buffer: Buffer.from(readFileSync(sample("insurance_certificate.txt"))),
      },
    },
  });

  // Assert: response status, document status, and audit event
  expect(uploadRes.status(), await uploadRes.text()).toBe(201);
  const document = await uploadRes.json();
  expect(document.status).toBe("processing");
  expect(document.kind).toBe("insurance_certificate");
  expect(document.vendor_id).toBe(vendor.id);

  const auditRes = await member.get(`/api/vendors/${vendor.id}/audit`);
  expect(auditRes.status(), await auditRes.text()).toBe(200);
  const audit = await auditRes.json();
  expect(audit.items.map((e: { action: string }) => e.action)).toContain("document.uploaded");
});
